/// <summary>
///    Sets the purchase release order fields.
/// </summary>
public void  setPurchTable()
{
    PurchAgreementHeaderDefault purchAgreementHeaderDefault = PurchAgreementHeaderDefault::findPurchAgreementHeader(createFromPurchAgreement.RecId);

    next setPurchTable();

    purchTable.AVARUMPurchUnionId        = PurchAgreementHeaderDefault.AVARUMPurchUnionId;
}

/// <summary>
/// set purch line extension fields
/// </summary>
public void setPurchLine()
{
    next setPurchLine();

    purchLine.AVARUMPlanAttrDimId=createFromAgreementLine.AVARUMPlanAttrDimId;
}
